module freq_div(
    input CLK_in,
    input RST,
    output CLK_50,
    output CLK_10,
    output CLK_1
);

reg [3:0] cnt_50 = 0;
reg [3:0] cnt_10 = 0;
reg [3:0] cnt_1 = 0;

always @(posedge CLK_in or posedge RST) begin
    if (RST) begin
        cnt_50 <= 0;
        cnt_10 <= 0;
        cnt_1 <= 0;
    end
    else begin
        cnt_50 <= cnt_50 + 1;
        cnt_10 <= cnt_10 + 1;
        cnt_1 <= cnt_1 + 1;
    end
end

assign CLK_50 = cnt_50[0];
assign CLK_10 = cnt_10[3];
assign CLK_1 = cnt_1[3];

endmodule
